<?php
function page_products(array $u):void {
 $manager=is_manager($u);$myCoop=$u['role']==='coop';$coops=$myCoop?' WHERE p.coop_id=?':'';$params=$myCoop?[$u['coop_id']]:[];
 $products=rows('SELECT p.*,c.name coop_name,r.name raw_name FROM products p JOIN cooperatives c ON c.id=p.coop_id JOIN raw_types r ON r.id=p.raw_type_id'.$coops.' ORDER BY p.id DESC',$params);
 if($myCoop){$coop=one('SELECT * FROM cooperatives WHERE id=?',[$u['coop_id']]);$types=rows('SELECT id,name FROM raw_types WHERE id=?',[$coop['specialty_raw_type_id']]);$accepted=rows("SELECT a.*,b.batch_code,COALESCE((SELECT SUM(l.input_qty) FROM production_logs l WHERE l.allocation_id=a.id),0) used FROM allocations a JOIN raw_batches b ON b.id=a.batch_id WHERE a.coop_id=? AND a.status IN ('accepted','completed') ORDER BY a.id DESC",[$u['coop_id']]);}
 if($myCoop):?><div class="row g-4 mb-4"><div class="col-lg-6"><div class="panel panel-pad h-100"><h5>Daftarkan jenis produk</h5><p class="helper">Produk jadi dimulai dengan stok 0. Stok bertambah hanya dari catatan produksi.</p><form method="post" class="row g-3"><?=csrf_input()?><input type="hidden" name="action" value="new_product"><div class="col-md-6"><?php field('Kode SKU unik','sku');?></div><div class="col-md-6"><?php field('Nama produk','name');?></div><div class="col-12"><?php select_field('Asal jenis limbah','raw_type_id',array_column($types,'name','id'));?></div><div class="col-md-6"><?php field('Harga jual per kg (Rp)','price','number','','required min="1" step="0.01"');?></div><div class="col-md-6"><?php field('Deskripsi','description','text','','');?></div><div class="col-12"><button class="btn btn-coco">Simpan produk</button></div></form></div></div><div class="col-lg-6"><div class="panel panel-pad h-100"><h5>Catat konversi limbah → produk</h5><p class="helper">Masukkan kg limbah terpakai dan kg hasil produksi. Sistem akan menambah stok produk secara otomatis.</p><form method="post" class="row g-3"><?=csrf_input()?><input type="hidden" name="action" value="production"><div class="col-12"><label class="form-label">Alokasi diterima / sisa input</label><select class="form-select" name="allocation_id" required><option value="">Pilih alokasi</option><?php foreach($accepted as $a):$remain=(float)$a['quantity']-(float)$a['used'];if($remain>0):?><option value="<?=$a['id']?>"><?=e($a['batch_code'])?> · <?=number($remain)?> kg tersedia</option><?php endif;endforeach;?></select></div><div class="col-12"><label class="form-label">Produk hasil</label><select class="form-select" name="product_id" required><option value="">Pilih produk</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['sku'].' · '.$p['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><?php field('Input limbah (kg)','input_qty','number','','required step="0.01" min="0.01"');?></div><div class="col-md-6"><?php field('Output produk (kg)','output_qty','number','','required step="0.01" min="0.01"');?></div><div class="col-12"><?php field('Catatan produksi','notes','text','','');?></div><div class="col-12"><button class="btn btn-coco">Catat produksi</button></div></form></div></div></div><?php endif;?>
<div class="panel"><div class="panel-pad section-title mb-0"><h5>Inventaris produk olahan · <?=count($products)?></h5><span class="chip">Stok hasil produksi</span></div><div class="table-responsive"><table class="table"><thead><tr><th>SKU / Produk</th><th>Koperasi</th><th>Asal limbah</th><th>Harga</th><th>Stok</th><th>Status</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><strong><?=e($p['name'])?></strong><div class="helper"><?=e($p['sku'])?></div></td><td><?=e($p['coop_name'])?></td><td><?=e($p['raw_name'])?></td><td><?=money($p['price'])?> / kg</td><td><strong><?=number($p['stock'])?></strong> kg</td><td><?=((int)$p['is_active'])?'<span class="badge text-bg-success">Aktif</span>':'<span class="badge text-bg-secondary">Nonaktif</span>'?></td></tr><?php endforeach;?></tbody></table><?php if(!$products)table_empty('Belum ada produk.');?></div></div>
<?php }
